/**
 * partsLibrary — the source of truth for circuit parts.
 *
 * Parts come from two places:
 *  1. Built-in tinyStudio boards (the tiny* family), whose Fritzing-style
 *     breadboard art lives in assets/tinyboards/ and is generated by
 *     `scripts/gen-tinyboards.py`.
 *  2. The Fritzing-imported library under assets/parts/, generated by
 *     `scripts/fritzing-import.mjs`. Each part is its own JSON file grouped by
 *     family and lazy-loaded on demand (so opening one family doesn't pull the
 *     SVGs for the whole catalogue).
 *
 * Both share one schema. Pin coordinates are pixels @ 96 DPI relative to the
 * part's top-left — the same space Wokwi uses — so a part drops straight into
 * diagram.json. A part can carry a `breadboard` and/or `schematic` view; pin
 * NAMES are stable across views, which is what lets connections survive a view
 * switch and stay valid Wokwi data.
 */

import { compareCategories, resolveNaming } from '../circuit/parts/naming'
import { invalidateSymbol } from '../circuit/parts/symbols'
import manifestJson from '../assets/parts/index.json'
import tinycoreArt from '../assets/tinyboards/tinycore.svg?raw'
import tinyglowArt from '../assets/tinyboards/tinyglow.svg?raw'
import tinyprotoArt from '../assets/tinyboards/tinyproto.svg?raw'
import tinysniffArt from '../assets/tinyboards/tinysniff.svg?raw'
import tinyspeakArt from '../assets/tinyboards/tinyspeak.svg?raw'
import tinydisplayArt from '../assets/tinyboards/tinydisplay.svg?raw'

export type ViewKind = 'breadboard' | 'schematic'

export interface PartView {
  svg: string
  w: number
  h: number
  pins: Record<string, [number, number]>
  /** pin names with a bendable rubber-band leg in this view (Fritzing
   * legId — LED/resistor class parts). Breadboard view only in practice. */
  legs?: string[]
}

export interface PartDef {
  type: string
  /** Display name (human-readable — see circuit/parts/naming). */
  label: string
  /** Display category — the group this part sits in, in the components rail. */
  family?: string
  /**
   * Keyword string used for SPICE emitter + refdes matching, kept separate
   * from the display category so renaming a category can never change how a
   * part simulates. Falls back to `family` when absent.
   */
  simFamily?: string
  /** Explicit refdes prefix (R, C, D, Q…) when the part knows better. */
  prefix?: string
  sub?: string
  accent?: string
  builtin?: boolean
  icon?: string
  views: Partial<Record<ViewKind, PartView>>
}

export interface PartMeta {
  type: string
  label: string
  /** Display category (see circuit/parts/naming). */
  family: string
  /** Keyword string for sim/refdes matching — never the display category. */
  simFamily?: string
  prefix?: string
  familySlug?: string
  views: ViewKind[]
  pins: number
  icon?: string
  file?: string
  builtin?: boolean
}

// ── built-in tinyStudio boards ───────────────────────────────────────────────
// Fritzing-style breadboard art for the tinyBoard family, drawn to the real
// hardware: a 1.9in (48.26 mm) regular octagon on a 0.1in grid, with component
// placement, silkscreen and colours measured off the product photos.
//
// Every tinyBoard carries the SAME 25-pin stack connector — 8 pins up the left
// (ANALOG), 8 up the right (DIGITAL), 9 across the bottom (SERIAL + power) —
// which is what lets them stack, so one pin map serves the whole family.
// tinyProto adds its 183-hole prototyping cross on the same 0.1in lattice.
//
// The art is generated: `python3 scripts/gen-tinyboards.py` rewrites
// assets/tinyboards/*.svg. Edit the generator, not the SVGs.

