/**
 * The five silkscreened buses on tinyProto (the ringed hole groups beside the
 * power pins). Every other hole is its own electrical island, exactly like the
 * real board — no breadboard-style shared rows.
 */
export const TINYPROTO_BUSES: string[][] = [
  ['A.5', 'B.5', 'C.5', 'D.2', 'D.3', 'D.4'],
  ['A.6', 'B.6', 'C.6'],
  ['M.11', 'N.11', 'O.11'],
  ['M.12', 'N.12', 'O.12', 'L.13', 'L.14', 'L.15'],
  ['K.13', 'K.14', 'K.15']
]

/** Regular octagon inset 1px in a 48px box — the family silhouette. */
const OCTAGON = '14.5,1 33.5,1 47,14.5 47,33.5 33.5,47 14.5,47 1,33.5 1,14.5'

/** Palette glyph: the board outline in its own soldermask colour. */
function boardIcon(short: string, mask: string, accent: string, ink: string): string {
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48">` +
    `<polygon points="${OCTAGON}" fill="${mask}" stroke="${accent}" stroke-width="1.6"/>` +
    `<text x="24" y="27" font-family="sans-serif" font-size="8" font-style="italic" ` +
    `fill="${ink}" text-anchor="middle">${short}</text></svg>`
  )
}

function board(
  type: string,
  label: string,
  art: string,
  opts: { sub: string; mask: string; accent: string; ink?: string; protoHoles?: boolean }
): PartDef {
  return {
    type,
    label,
    family: 'tinyStudio',
    sub: opts.sub,
    accent: opts.accent,
    builtin: true,
    icon: boardIcon(label.slice(4), opts.mask, opts.accent, opts.ink || '#ffffff'),
    views: {
      breadboard: {
        svg: art,
        w: BOARD_PX,
        h: BOARD_PX,
        pins: opts.protoHoles ? { ...STACK_PINS, ...PROTO_HOLES } : { ...STACK_PINS }
      }
    }
  }
}

